import httpximport asyncio# ── Config ────────────────────────────────────────────────────────────────────EVENT_URL = (    "https://m.betking.com/en-ng/sports/live/api/event"    "?areaId=2&fixtureId={fixture_id}"    "&_data=routes%2F%28%24locale%29.sports.live.api.event")EVENT_HEADERS = {    "User-Agent":      "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0",    "Accept":          "*/*",    "Accept-Language": "en-US,en;q=0.5",    "Dnt":             "1",    "Sec-Gpc":         "1",    "Sec-Fetch-Dest":  "empty",    "Sec-Fetch-Mode":  "cors",    "Sec-Fetch-Site":  "same-origin",    "Priority":        "u=4",    "Te":              "trailers",}# Market typeId for "game - total points"GAME_TOTAL_TYPE_ID = 10637TARGET_LINES       = [15.5, 16.5]   # checked in order; first qualifying winsTARGET_SELECTION   = "Over"MIN_ODD            = 1.18# Minimum loser score per set — loser must score >= 7 in each of the 4 setsSET_THRESHOLDS = [7, 7, 7, 7]# ── Form API ──────────────────────────────────────────────────────────────────FORM_URL = (    "https://lmt.fn.sportradar.com/common/en/Etc:UTC/gismo"    "/stats_match_form/{match_id}?T={token}")FORM_HEADERS = {    "User-Agent":      "Mozilla/5.0 (X11; Linux x86_64; rv:140.0) Gecko/20100101 Firefox/140.0",    "Accept":          "*/*",    "Accept-Language": "en-US,en;q=0.5",    "Origin":          "https://m.betking.com",    "Referer":         "https://m.betking.com/",    "Sec-Fetch-Dest":  "empty",    "Sec-Fetch-Mode":  "cors",    "Sec-Fetch-Site":  "cross-site",    "Sec-Gpc":         "1",    "Te":              "trailers",}FORM_WIN_PTS  = 20   # W = 20 pts, L = 0 ptsFORM_MIN      = 20   # both players must have at least thisFORM_MAX_GAP  = 20   # max allowed difference between the two players# ── Helpers ───────────────────────────────────────────────────────────────────def _build_referer(event_id: int) -> str:    return f"https://m.betking.com/en-ng/sports/live/{event_id}"def _resolve_market_name(market: dict) -> str:    """    Resolve '{gamenr} game - total points {line}' using specifiers.    e.g. specialValue=4, lineValue=16.5 → 'Set 4 - Total Points'    """    gamenr = market.get("specifiers", {}).get("gamenr") or market.get("specialValue", "?")    return f"Set {gamenr} - Total Points"def _parse_period_scores(period_scores: str) -> list[tuple[int, int]]:    """Parse '6:11 - 11:9 - 11:7' into [(6,11), (11,9), (11,7)]."""    sets = []    for part in period_scores.split(" - "):        part = part.strip()        if not part or ":" not in part:            continue        try:            h, a = part.split(":")            sets.append((int(h), int(a)))        except ValueError:            continue    return setsdef _calc_form_score(form: list) -> int:    """First 5 entries. W = 20 pts, L = 0 pts. Max = 100."""    return sum(FORM_WIN_PTS for entry in form[:5] if entry.get("type") == "W")def _form_qualifies(home: int, away: int) -> bool:    """    Both players must have form >= FORM_MIN (20).    The gap between them must be <= FORM_MAX_GAP (20).    Valid pairs: (20,20),(20,40),(40,40),(40,60),(60,60),(60,80),(80,80),(80,100),(100,100)    """    if home < FORM_MIN or away < FORM_MIN:        return False    return abs(home - away) <= FORM_MAX_GAPdef _sets_qualify(sets: list[tuple[int, int]]) -> bool:    """    Check first 4 sets. In each set the loser must have scored    at least the threshold for that set position.    """    if len(sets) < 4:        return False    for i, threshold in enumerate(SET_THRESHOLDS):        h, a = sets[i]        loser_score = min(h, a)        if loser_score < threshold:            return False    return Truedef _find_market(markets: list, line: float) -> dict | None:    """Find the game total points market with the given lineValue."""    for market in markets:        if market.get("marketTypeId") != GAME_TOTAL_TYPE_ID:            continue        if market.get("lineValue") != line:            continue        return market    return Nonedef _get_over_selection(market: dict) -> dict | None:    """Return the Over selection if active and odd meets minimum."""    for sel in market.get("selections", []):        if sel.get("name") != TARGET_SELECTION:            continue        odd = sel.get("odd", {})        if odd.get("statusId") != 1:            return None        if odd.get("value", 0.0) < MIN_ODD:            return None        return sel    return Nonedef _pick_market(markets: list) -> tuple[dict, dict, float] | tuple[None, None, None]:    """    Try TARGET_LINES in order. Return (market, over_sel, line) for the    first line whose Over selection exists and meets MIN_ODD, else (None, None, None).    """    for line in TARGET_LINES:        market = _find_market(markets, line)        if market is None:            print(f"[analyzer] no market : game total {line} not found")            continue        over_sel = _get_over_selection(market)        if over_sel is None:            print(f"[analyzer] no signal : Over {line} suspended or odd below {MIN_ODD}")            continue        return market, over_sel, line    return None, None, None# ── Fetch match form ──────────────────────────────────────────────────────────async def fetch_match_form(event_id: int, token: str) -> tuple[int, int] | None:    """    Call Sportradar stats_match_form for event_id using today's token.    Returns (home_form_score, away_form_score) or None on failure.    """    url = FORM_URL.format(match_id=event_id, token=token)    try:        async with httpx.AsyncClient(http2=True, timeout=15.0) as client:            resp = await client.get(url, headers=FORM_HEADERS)        if resp.status_code != 200:            print(f"[analyzer] form failed   {event_id}: HTTP {resp.status_code}")            return None        if not resp.text or not resp.text.strip():            print(f"[analyzer] form failed   {event_id}: empty response")            return None        data  = resp.json()        doc   = (data.get("doc") or [{}])[0]        teams = doc.get("data", {}).get("teams", {})        home_form  = teams.get("home", {}).get("form", [])        away_form  = teams.get("away", {}).get("form", [])        home_score = _calc_form_score(home_form)        away_score = _calc_form_score(away_form)        return home_score, away_score    except Exception as e:        print(f"[analyzer] form error    {event_id}: {e}")        return None# ── Fetch event ───────────────────────────────────────────────────────────────async def fetch_event(event_id: int) -> dict | None:    url = EVENT_URL.format(fixture_id=event_id)    try:        import os        from supabase import create_client        base   = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))        config = {}        with open(os.path.join(base, "db.txt")) as f:            for line in f:                line = line.strip()                if "=" in line and not line.startswith("#"):                    k, _, v = line.partition("=")                    config[k.strip()] = v.strip().strip('"')        sb     = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])        cookie = sb.table("betking").select("cookie").eq("id", 1).single().execute().data["cookie"]    except Exception as e:        print(f"[analyzer] cookie err {event_id}: {e}")        cookie = ""    headers = {        **EVENT_HEADERS,        "Referer": _build_referer(event_id),        "Cookie":  cookie,    }    try:        async with httpx.AsyncClient(http2=True, timeout=15.0) as client:            resp = await client.get(url, headers=headers)        if resp.status_code != 200:            print(f"[analyzer] fetch failed {event_id}: HTTP {resp.status_code}")            return None        if not resp.text or not resp.text.strip():            print(f"[analyzer] fetch failed {event_id}: empty response")            return None        data = resp.json()        if not isinstance(data, dict) or "event" not in data:            print(                f"[analyzer] fetch failed {event_id}: unexpected response"                f" | keys={list(data.keys()) if isinstance(data, dict) else type(data)}"            )            return None        return data    except Exception as e:        print(f"[analyzer] fetch error {event_id}: {e}")        return None# ── Main entry point ──────────────────────────────────────────────────────────async def analyze(event_id: int, staker=None) -> None:    raw = await fetch_event(event_id)    if raw is None:        return    event   = raw.get("event") or {}    markets = raw.get("markets", [])    match_name    = event.get("name", "?")    period_scores = event.get("periodScores", "")    tournament_id = event.get("tournamentId")    tournament    = event.get("tournamentName", "?")    category_id   = event.get("categoryId")    category_name = event.get("categoryName", "")    event_date    = event.get("date", "")    match_status  = event.get("matchStatus", "")    # Extract Sportradar match ID from "sr:match:72026422"    provider_id  = event.get("source", {}).get("providerId", "")    sr_match_id  = None    if provider_id.startswith("sr:match:"):        try:            sr_match_id = int(provider_id.split(":")[-1])        except ValueError:            pass    print(f"[analyzer] checking  : {match_name}")    print(f"[analyzer] sets      : {period_scores}")    print(f"[analyzer] status    : {match_status}")    print(f"[analyzer] sr id     : {sr_match_id or 'NOT FOUND'}")    sets = _parse_period_scores(period_scores)    if not _sets_qualify(sets):        details = " | ".join(            f"set{i+1}: {h}:{a} (loser={min(h,a)}>={SET_THRESHOLDS[i]}?{'YES' if min(h,a)>=SET_THRESHOLDS[i] else 'NO'})"            for i, (h, a) in enumerate(sets[:4])        )        print(f"[analyzer] no signal : sets did not qualify | {details}")        print()        return    if sr_match_id is None:        print(f"[analyzer] no signal : providerId missing or not sr:match — skipping")        print()        return    print(f"[analyzer] sets ok   : all 4 thresholds met")    # ── Form check ────────────────────────────────────────────────────────────    from module.betlist import get_today_token    token = get_today_token()    if not token:        print(f"[analyzer] no signal : token missing, cannot check form")        print()        return    form_result = await fetch_match_form(sr_match_id, token)    if form_result is None:        print(f"[analyzer] no signal : form fetch failed")        print()        return    home_form, away_form = form_result    print(f"[analyzer] form      : home={home_form}/100  away={away_form}/100")    if not _form_qualifies(home_form, away_form):        print(            f"[analyzer] no signal : form did not qualify "            f"(need both >= {FORM_MIN} and gap <= {FORM_MAX_GAP}, got {home_form}/{away_form})"        )        print()        return    print(f"[analyzer] form ok   : {home_form}/{away_form} — both qualify")    market, over_sel, chosen_line = _pick_market(markets)    if market is None:        print(f"[analyzer] no signal : no qualifying line found in {TARGET_LINES}")        print()        return    odd_value      = over_sel["odd"]["value"]    selection_id   = over_sel["id"]    gamenr         = market.get("specifiers", {}).get("gamenr") or market.get("specialValue", "?")    resolved_name  = _resolve_market_name(market)    selection_name = f"Over ({gamenr})-{resolved_name}"    print(f"[analyzer] signal    : {match_name} | Over {chosen_line} @ {odd_value}")    print()    payload = {        "eventId":         event_id,        "matchId":         event_id,        "parentEventId":   event_id,        "matchName":       match_name,        "matchKMId":       event_id,        "tournamentId":    tournament_id,        "tournamentName":  tournament,        "categoryId":      category_id,        "categoryName":    category_name,        "eventDate":       event_date,        "marketId":        market["marketId"],        "marketName":      resolved_name,        "marketTypeId":    market["marketTypeId"],        "marketKMId":      market["marketId"] - 240_000_000,        "specialValue":    str(market.get("specialValue", "")),        "selectionId":     selection_id,        "selectionName":   selection_name,        "selectionKMId":   selection_id - 820_000_000,        "selectionTypeId": over_sel.get("typeId"),        "oddValue":        odd_value,        "lineValue":       chosen_line,        "periodScores":    period_scores,    }    if staker is not None:        await staker.queue(payload)